<?php
namespace App\Services;use App\Models\PromoCode;use App\Models\User;use Illuminate\Support\Collection;use Illuminate\Validation\ValidationException;
class PromoCodeService{public function calculate(?string $code,User $user,Collection $items,int $subtotal):array{if(blank($code))return[null,0];$p=PromoCode::whereRaw('UPPER(code)=?',[strtoupper(trim($code))])->first();if(!$p||!$p->is_active||($p->starts_at&&$p->starts_at->isFuture())||($p->expires_at&&$p->expires_at->isPast()))throw ValidationException::withMessages(['promo_code'=>'Промокод недействителен.']);if($subtotal<$p->minimum_amount)throw ValidationException::withMessages(['promo_code'=>'Минимальная сумма не достигнута.']);if(($p->usage_limit&&$p->usages()->count()>=$p->usage_limit)||$p->usages()->where('user_id',$user->id)->count()>=$p->per_user_limit)throw ValidationException::withMessages(['promo_code'=>'Лимит промокода исчерпан.']);$eligible=$items->filter(fn($i)=>(!$p->product_id||$i->product_id==$p->product_id)&&(!$p->category_id||$i->product->category_id==$p->category_id)&&(!$p->seller_id||$i->product->seller_id==$p->seller_id))->sum(fn($i)=>$i->product->price*$i->quantity);if($eligible<1)throw ValidationException::withMessages(['promo_code'=>'Промокод не подходит к корзине.']);$d=$p->type==='percent'?(int)round($eligible*$p->value/100):min($p->value,$eligible);return[$p,min($p->maximum_discount?min($d,$p->maximum_discount):$d,$subtotal)];}}
